"""Optional user/default language → Opus MT model map."""

from __future__ import annotations

import json
import logging
from functools import lru_cache
from pathlib import Path
from typing import Any

_log = logging.getLogger("transub_engine.mt.lang_map")

# Built-in defaults (primary subtag → model id)
DEFAULT_LANGUAGE_MAP: dict[str, str] = {
    "ja": "opus-mt-ja-zh",
    "jp": "opus-mt-ja-zh",
    "jpn": "opus-mt-ja-zh",
    "ko": "opus-mt-ko-zh",
    "kor": "opus-mt-ko-zh",
    "kr": "opus-mt-ko-zh",
    "de": "opus-mt-de-zh",
    "deu": "opus-mt-de-zh",
    "ger": "opus-mt-de-zh",
    "es": "opus-mt-es-zh",
    "spa": "opus-mt-es-zh",
    "fi": "opus-mt-fi-zh",
    "fin": "opus-mt-fi-zh",
    "sv": "opus-mt-sv-zh",
    "swe": "opus-mt-sv-zh",
    "en": "opus-mt-en-zh",
    "eng": "opus-mt-en-zh",
}


def mt_language_map_path() -> Path:
    from ..paths import get_data_root

    return get_data_root() / "mt_language_map.json"


def clear_language_map_cache() -> None:
    load_language_map.cache_clear()


@lru_cache(maxsize=1)
def load_language_map() -> dict[str, str]:
    """Merge defaults with optional ``{data}/mt_language_map.json`` overrides."""
    merged = dict(DEFAULT_LANGUAGE_MAP)
    path = mt_language_map_path()
    if not path.is_file():
        return merged
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as err:
        _log.warning("mt_language_map unreadable (%s): %s", path, err)
        return merged
    if not isinstance(data, dict):
        return merged
    for key, val in data.items():
        k = str(key or "").strip().lower().replace("_", "-")
        # Allow "fr-FR" → store under full and primary
        v = str(val or "").strip()
        if not k or not v:
            continue
        merged[k] = v
        primary = k.split("-", 1)[0]
        if primary and primary not in data:
            # Only fill primary if user didn't set a more specific key alone
            merged.setdefault(primary, v)
    return merged


def resolve_mt_model_for_language(language: str, explicit: str | None = None) -> str:
    if explicit and str(explicit).strip():
        return str(explicit).strip()
    lang = str(language or "").lower().replace("_", "-").strip()
    mapping = load_language_map()
    if lang in mapping:
        return mapping[lang]
    primary = lang.split("-", 1)[0].strip() if lang else ""
    if primary in mapping:
        return mapping[primary]
    # Prefix match (ja-JP → ja)
    for key, model in mapping.items():
        if lang.startswith(key) or (primary and key.startswith(primary)):
            if key == primary or lang.startswith(f"{key}-"):
                return model
    return mapping.get("en", "opus-mt-en-zh")


def write_default_language_map_if_missing() -> Path:
    """Create a commented-friendly JSON starter for users (no comments in JSON)."""
    path = mt_language_map_path()
    if path.exists():
        return path
    starter: dict[str, Any] = {
        "_comment": "Override language → Opus MT model id. Delete keys to use built-ins.",
        "ja": "opus-mt-ja-zh",
        "ko": "opus-mt-ko-zh",
        "en": "opus-mt-en-zh",
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(starter, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    clear_language_map_cache()
    return path
